style.css:
@-moz-document domain("codeforces.com") {
/* ===== ФОН С АНИМЕ-ТЯНКАМИ ===== */
  html, body {
    background-color: #0d0d14 !important;
    background-image: 
      url("https://i.imgur.com/8yQ8yQ8.jpg"),   /* ← замени на свою картинку */
      url("https://i.imgur.com/9zR9zR9.jpg");   /* ← и эту тоже */
    background-size: 35%, 35%;
    background-position: left bottom, right bottom;
    background-repeat: no-repeat, no-repeat;
    background-attachment: fixed, fixed;
    /* Лёгкое затемнение, чтобы картинки не отвлекали */
    position: relative;
  }

  /* Тёмная вуаль поверх фона для читаемости */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(10, 8, 20, 0.72);
    backdrop-filter: blur(3px);
    z-index: -1;
    pointer-events: none;
  }

  /* ===== ОСНОВНОЙ КОНТЕНТ ===== */
  #pageContent,
  .content-with-sidebar,
  .roundbox,
  .datatable,
  .problem-statement {
    background: rgba(20, 18, 30, 0.85) !important;
    color: #e8e6f0 !important;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(255, 105, 180, 0.15);
  }

  /* ===== ШАПКА ===== */
  #header,
  .menu-list-container,
  .second-level-menu,
  .second-level-menu-list {
    background: rgba(15, 12, 25, 0.92) !important;
    border-bottom: 1px solid rgba(255, 105, 180, 0.4) !important;
  }

  /* ===== ССЫЛКИ ===== */
  a, a:visited {
    color: #ff9ecb !important;
    transition: color 0.2s ease;
  }
  a:hover {
    color: #ffd1e8 !important;
    text-shadow: 0 0 8px rgba(255, 105, 180, 0.8);
  }

  /* ===== ТЕКСТ ===== */
  p, span, div, li, td, th, h1, h2, h3, h4, label {
    color: #e8e6f0 !important;
  }

  /* ===== ЗАГОЛОВКИ ===== */
  h1, h2, h3, .caption {
    color: #ffb3d9 !important;
    text-shadow: 0 0 10px rgba(255, 105, 180, 0.4);
  }

  /* ===== ВВОД / TEXTAREA ===== */
  input, textarea, select {
    background: rgba(30, 26, 45, 0.9) !important;
    color: #fff !important;
    border: 1px solid rgba(255, 105, 180, 0.4) !important;
    border-radius: 6px;
  }
  input:focus, textarea:focus {
    outline: none;
    border-color: #ff69b4 !important;
    box-shadow: 0 0 10px rgba(255, 105, 180, 0.5);
  }

  /* ===== КНОПКИ ===== */
  .button, input[type="submit"], button {
    background: linear-gradient(135deg, #ff69b4, #b06ab3) !important;
    color: #fff !important;
    border: none !important;
    border-radius: 8px !important;
    font-weight: 600;
    transition: all 0.2s ease;
  }
  .button:hover, input[type="submit"]:hover, button:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 15px rgba(255, 105, 180, 0.6);
  }

  /* ===== МОНОКОД (задачи, примеры) ===== */
  pre, code, .test-example-line {
    background: rgba(12, 10, 22, 0.95) !important;
    color: #a8e6cf !important;
    border-radius: 6px;
    border-left: 3px solid #ff69b4;
  }

  /* ===== САЙДБАР / МЕНЮ ===== */
  .sidebar, #sidebar, .sidebox {
    background: rgba(20, 18, 30, 0.88) !important;
    border-radius: 10px;
  }

  /* ===== РЕЙТИНГ / ТАБЛИЦЫ ===== */
  table {
    background: transparent !important;
  }
  tr:nth-child(even) {
    background: rgba(255, 105, 180, 0.05) !important;
  }

  /* ===== СКРОЛЛБАР ===== */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: #0d0d14; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(#ff69b4, #b06ab3);
    border-radius: 10px;
  }

  /* ===== КАРТИНКИ-ЛОГО НЕ ЛОМАЕМ ===== */
  #header img, .logo {
    filter: drop-shadow(0 0 6px rgba(255, 105, 180, 0.6));
  }
}
